import{_ as d,o as n,c as e,a5 as a}from"./chunks/framework.CsGesDJn.js";const s=JSON.parse('{"title":"Mobile video → Task sync — Test","description":"","frontmatter":{},"headers":[],"relativePath":"feature/mobile-video-task-sync/test.md","filePath":"feature/mobile-video-task-sync/test.md"}'),h={name:"feature/mobile-video-task-sync/test.md"};function i(r,t,c,o,g,l){return n(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="mobile-video-→-task-sync-—-test" tabindex="-1">Mobile video → Task sync — Test <a class="header-anchor" href="#mobile-video-→-task-sync-—-test" aria-label="Permalink to &quot;Mobile video → Task sync — Test&quot;">​</a></h1><h2 id="tu-đong" tabindex="-1">Tự động <a class="header-anchor" href="#tu-đong" aria-label="Permalink to &quot;Tự động&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Kiểm tra</th><th>Mong đợi</th></tr></thead><tbody><tr><td>A1</td><td>Validator: <code>isom</code>, <code>mp42</code>, <code>qt</code> khai <code>video/mp4</code> hoặc <code>video/quicktime</code></td><td>Qua</td></tr><tr><td>A2</td><td>Policy: JPEG vào TASK</td><td>Qua; PDF vào TASK bị từ chối</td></tr><tr><td>A3</td><td><code>GET materials?taskId=</code></td><td>Chỉ trả tệp của task; Client không thấy INTERNAL</td></tr><tr><td>A4</td><td>Client đọc bài có media INTERNAL đã ghim</td><td>Có URL</td></tr><tr><td>A5</td><td>Pipeline: session hết hạn</td><td>Upload lại, thành công</td></tr><tr><td>A6</td><td>Pipeline: <code>TASK_NOT_ASSIGNED</code></td><td><code>FAILED</code>, không thử lại</td></tr><tr><td>A7</td><td>Khởi động với mục <code>UPLOADING</code></td><td>Về <code>QUEUED</code></td></tr><tr><td>A8</td><td>Chỉ Wi-Fi trên 4G</td><td>Không chạy; có Wi-Fi thì chạy</td></tr><tr><td>A9</td><td>Web: danh sách, rỗng, đưa vào bài</td><td>Đúng trạng thái và payload</td></tr></tbody></table><h2 id="api-that-docker-rieng-postgres-mongo-replica-set-minio" tabindex="-1">API thật (Docker riêng: Postgres, Mongo replica set, MinIO) <a class="header-anchor" href="#api-that-docker-rieng-postgres-mongo-replica-set-minio" aria-label="Permalink to &quot;API thật (Docker riêng: Postgres, Mongo replica set, MinIO)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Bước</th><th>Mong đợi</th></tr></thead><tbody><tr><td>B1</td><td>Creator tạo session, PUT file <code>.mov</code>, confirm</td><td>Material <code>READY</code>, có <code>taskId</code></td></tr><tr><td>B2</td><td>Như B1 với MP4 <code>isom</code> và JPEG</td><td><code>READY</code></td></tr><tr><td>B3</td><td><code>GET materials?taskId=</code> bằng Manager</td><td>Thấy tệp; Client không thấy</td></tr><tr><td>B4</td><td>Lưu bài với <code>materialId</code>, gửi duyệt</td><td>Bài có media; task <code>IN_REVIEW</code></td></tr><tr><td>B5</td><td>Web mở task</td><td>Thấy tệp, xem trước, chuyển ngôn ngữ và theme không vỡ</td></tr></tbody></table><h2 id="thiet-bi-nguoi-dung-xac-nhan-dev-build" tabindex="-1">Thiết bị (người dùng xác nhận, dev build) <a class="header-anchor" href="#thiet-bi-nguoi-dung-xac-nhan-dev-build" aria-label="Permalink to &quot;Thiết bị (người dùng xác nhận, dev build)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Bước</th><th>Mong đợi</th></tr></thead><tbody><tr><td>C1</td><td>iPhone quay clip</td><td>Tự upload, web thấy trong khoảng 15s</td></tr><tr><td>C2</td><td>Android quay clip</td><td>Như C1</td></tr><tr><td>C3</td><td>Bật máy bay giữa upload, tắt lại</td><td>Tự tiếp tục</td></tr><tr><td>C4</td><td>Tắt app giữa upload, mở lại</td><td>Tự tiếp tục</td></tr><tr><td>C5</td><td>Đổi FPS 24/30/60</td><td>Metadata file đúng FPS</td></tr><tr><td>C6</td><td>Ảnh HEIC trên iPhone</td><td>Lên task dạng JPEG</td></tr><tr><td>C7</td><td>Quay quá mục tiêu thời lượng</td><td>Không tự dừng</td></tr><tr><td>C8</td><td>Quay 3 take liên tiếp</td><td>Ở lại camera, giữ cài đặt, số take tăng 01, 02, 03</td></tr><tr><td>C9</td><td>Đang quay thì vuốt back (iPhone) và bấm back (Android)</td><td>Không thoát, clip vẫn lưu khi dừng</td></tr><tr><td>C10</td><td>So khung trên màn với file đã quay</td><td>Video không bị cắt thêm, khung canh đúng vị trí</td></tr><tr><td>C11</td><td>Từ chối quyền camera, mở lại màn quay</td><td>Có nút Mở Cài đặt, bật quyền xong quay được</td></tr><tr><td>C12</td><td>Chạm một take trong chi tiết Task</td><td>Mở được video bằng trình phát của máy</td></tr><tr><td>C13</td><td>Bật dark mode, đi hết luồng</td><td>Không còn nền sáng lẫn vào, chữ đọc rõ</td></tr></tbody></table><h2 id="ket-qua-chay-emulator-2026-11-02" tabindex="-1">Kết quả chạy emulator (2026-11-02) <a class="header-anchor" href="#ket-qua-chay-emulator-2026-11-02" aria-label="Permalink to &quot;Kết quả chạy emulator (2026-11-02)&quot;">​</a></h2><p>Pixel_9a, Android 17 (API 37), camera ảo, debug build, stack e2e riêng. Chưa thay thế xác nhận trên máy thật.</p><table tabindex="0"><thead><tr><th>#</th><th>Kết quả</th><th>Ghi chú</th></tr></thead><tbody><tr><td>C2</td><td>Đạt một phần</td><td>Quay, tự tải lên, material <code>READY</code>, đúng dung lượng. Chưa kiểm tra phía web</td></tr><tr><td>C4</td><td>Đạt một phần</td><td>Đưa app ra nền rồi mở lại: hàng đợi chạy tiếp và thử lại được. Chưa tắt app giữa lúc upload</td></tr><tr><td>C8</td><td>Đạt</td><td>Ở lại camera, số take tăng 01 → 04. Chưa kiểm tra giữ cài đặt</td></tr><tr><td>C9</td><td>Đạt phần Android</td><td>Nút back bị chặn, có cảnh báo. Chưa thử iPhone</td></tr><tr><td>C10</td><td>Có vấn đề</td><td>File 720x1280 (9:16) nhưng preview 4:3; chọn 1080p ra 720p. Cần xác nhận trên máy thật</td></tr><tr><td>C1, C3, C5, C6, C7, C11, C12, C13</td><td>Chưa chạy</td><td>Xem lượt chạy lại bên dưới</td></tr></tbody></table><h2 id="ket-qua-chay-lai-tren-emulator-2026-11-02-sau-khi-sua-ui" tabindex="-1">Kết quả chạy lại trên emulator (2026-11-02, sau khi sửa UI) <a class="header-anchor" href="#ket-qua-chay-lai-tren-emulator-2026-11-02-sau-khi-sua-ui" aria-label="Permalink to &quot;Kết quả chạy lại trên emulator (2026-11-02, sau khi sửa UI)&quot;">​</a></h2><p>Pixel_9a, debug build + Metro, stack e2e riêng. Vẫn chưa thay thế xác nhận trên máy thật.</p><table tabindex="0"><thead><tr><th>#</th><th>Kết quả</th><th>Ghi chú</th></tr></thead><tbody><tr><td>C3</td><td>Đạt</td><td>Cắt mạng lúc <code>UPLOADING</code>: take thành <code>FAILED</code>, có mạng lại tự tải tiếp đến <code>SYNCED</code> sau 9 giây</td></tr><tr><td>C4</td><td>Đạt</td><td>Tắt app lúc <code>UPLOADING</code>, mở lại thì tự tải tiếp đến <code>SYNCED</code>. Tắt app ngay sau khi dừng quay, trước khi clip vào hàng đợi, thì mất clip đó</td></tr><tr><td>C7</td><td>Đạt</td><td>Mục tiêu 15 giây, quay quá 30 giây, timer đổi màu, không tự dừng</td></tr><tr><td>C10</td><td>Đạt phần khung trên emulator</td><td>Preview đã cắt theo tỉ lệ file, khung canh nằm trong hình, nhãn hiện đúng 720p. Cần so với file trên máy thật</td></tr><tr><td>C11</td><td>Đạt phần emulator</td><td>Từ chối quyền thì có Mở Cài đặt. Cấp lại bằng <code>pm grant</code> thì quay được, chưa đi qua màn Cài đặt</td></tr><tr><td>C12</td><td>Đạt trên Android</td><td>Mở bằng trình xem video của máy (Google Photos trên emulator). iOS chưa kiểm tra</td></tr><tr><td>C13</td><td>Đạt phần đã xem</td><td>Home, Chi tiết Task, Tải tệp, màn quay ở theme tối của app. Công tắc theme xoay vòng sáng, tối, theo hệ thống</td></tr><tr><td>Histogram</td><td>Đạt</td><td>Góc phải trên của khung, không bị ngăn kéo và thẻ kịch bản che</td></tr><tr><td>Zebra</td><td>Đạt phần vị trí</td><td>Đã sửa lỗi lệch 180°. Kiểm tra bằng ngưỡng tạm 150 vì cảnh ảo không chạm 235</td></tr><tr><td>EV +2</td><td>Không kiểm chứng được</td><td>Giá trị đổi, nhưng hình và histogram của camera ảo gần như không đổi</td></tr><tr><td>Kim dB</td><td>Không kiểm chứng được</td><td>Luôn -60 dB dù bật <code>-allow-host-audio</code> và phát tiếng ra loa. Track âm thanh của file cũng gần như im lặng (khoảng 102 byte mỗi frame AAC), nên nghi mic ảo không nhận tiếng. Cần thử có tiếng thật trên máy thật</td></tr><tr><td>Motion</td><td>Đạt trên Expo Web, chưa kiểm tra lại trên Android</td><td>Khung 412x915: skeleton, nội dung hiện dần, tab drawer trồi nhẹ, thanh tab trượt, Reduce Motion bỏ dịch chuyển. Đổi 10 lần tab drawer với CPU chậm 6 lần không có màn trống. Emulator từng có 1 lần màn trống sau khi mở app, chưa tái hiện được (13 lần mở lại đều đạt); đã bỏ native driver ở 2 animation có thể che cả màn, cần xác nhận trên Android</td></tr><tr><td>C1, C5, C6</td><td>Chưa chạy</td><td>Cần iPhone, kiểm tra metadata file hoặc ảnh HEIC</td></tr></tbody></table><h2 id="ket-qua-tren-expo-web-dark-mode-va-ngon-ngu" tabindex="-1">Kết quả trên Expo Web (dark mode và ngôn ngữ) <a class="header-anchor" href="#ket-qua-tren-expo-web-dark-mode-va-ngon-ngu" aria-label="Permalink to &quot;Kết quả trên Expo Web (dark mode và ngôn ngữ)&quot;">​</a></h2><p>Khung 412x915, stack e2e riêng, vai trò Creator và Admin. Bộ dò tự động đo vùng nền sáng lớn, độ tương phản chữ/nền và chữ tiếng Việt còn sót trên phần đang hiển thị của mỗi màn. Chưa kiểm tra trên Android.</p><table tabindex="0"><thead><tr><th>Mục</th><th>Kết quả</th><th>Ghi chú</th></tr></thead><tbody><tr><td>Dark mode, các tab và menu More của Creator</td><td>Đạt</td><td>19 màn không còn vùng nền sáng lớn. Lỗi tương phản ở nút Lịch sử màn Tạo video AI đã sửa ở Button dùng chung</td></tr><tr><td>Dark mode, 8 màn chính của Admin</td><td>Đạt</td><td>Màn con, form và hộp thoại chỉ được chuyển bằng script, chưa mở hết để xem</td></tr><tr><td>Tiếng Anh, 19 màn của Creator</td><td>Đạt</td><td>Chỉ còn tên ngôn ngữ &quot;Tiếng Việt&quot; ở ô chọn, là đúng. Nội dung do backend trả về vẫn giữ nguyên ngôn ngữ gốc</td></tr><tr><td>Đổi ngôn ngữ trong phiên</td><td>Đạt</td><td>Cập nhật ngay, app quay về màn đầu của luồng</td></tr><tr><td>Đăng nhập Google</td><td>Đạt một phần</td><td>Google nhận client_id và redirect_uri, tới trang đăng nhập. Chưa đăng nhập hết luồng nên client secret chưa được kiểm chứng</td></tr></tbody></table><h2 id="ra-ban-dich-va-noi-dung-backend-chi-test-tu-đong-chua-mo-tren-trinh-duyet" tabindex="-1">Rà bản dịch và nội dung backend (chỉ test tự động, chưa mở trên trình duyệt) <a class="header-anchor" href="#ra-ban-dich-va-noi-dung-backend-chi-test-tu-đong-chua-mo-tren-trinh-duyet" aria-label="Permalink to &quot;Rà bản dịch và nội dung backend (chỉ test tự động, chưa mở trên trình duyệt)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Kết quả</th><th>Ghi chú</th></tr></thead><tbody><tr><td>Rà bản dịch tiếng Anh</td><td>Agent đã đọc hết, chưa có người đọc lại</td><td>Đã sửa các chuỗi sai nghĩa theo ngữ cảnh và thống nhất thuật ngữ. Placeholder khớp ở mọi khoá</td></tr><tr><td>Câu hệ thống từ backend</td><td>Đạt test tự động</td><td>Thông báo, lỗi đăng bài và lý do kiểm duyệt có bản tiếng Anh. Nội dung người dùng và AI, email, PDF, mẫu seed giữ nguyên</td></tr><tr><td>Thông báo lỗi API</td><td>Đạt test tự động</td><td>Mobile đọc <code>error.message</code>; tiếng Việt chỉ hiện với mã đã dịch, mã khác và lỗi 5xx giữ câu của màn hình</td></tr><tr><td>Creator vào <code>/requests</code> trên web</td><td>Đạt test tự động</td><td>Route đã chặn Creator, ẩn link Yêu cầu nội dung trong chi tiết Task</td></tr><tr><td>Owner xem Yêu cầu nội dung (web, mobile)</td><td>Đạt trên Expo Web</td><td>Mở danh sách và chi tiết. Backend trả mọi quyền thao tác là false nên Owner chỉ xem; form tạo vẫn đóng với Owner</td></tr></tbody></table><h2 id="quet-toan-bo-tren-expo-web-2026-11-03" tabindex="-1">Quét toàn bộ trên Expo Web (2026-11-03) <a class="header-anchor" href="#quet-toan-bo-tren-expo-web-2026-11-03" aria-label="Permalink to &quot;Quét toàn bộ trên Expo Web (2026-11-03)&quot;">​</a></h2><p>Khung 412x915, stack e2e riêng dựng lại từ schema và seed của dự án. Chưa kiểm tra trên Android hay iOS.</p><table tabindex="0"><thead><tr><th>Mục</th><th>Kết quả</th><th>Ghi chú</th></tr></thead><tbody><tr><td>Owner, Manager, Client, Creator, Admin: tối + tiếng Anh</td><td>Đạt</td><td>Mở cả màn con và form chính. Chữ tiếng Việt còn lại là dữ liệu seed hoặc tên thương hiệu</td></tr><tr><td>Owner: sáng + tiếng Việt</td><td>Đạt</td><td>Sửa chữ &quot;Đã kết nối&quot; tương phản thấp bằng token <code>successText</code>. Vai trò khác chưa quét ở chế độ này</td></tr><tr><td>Lỗi đăng nhập sai</td><td>Đạt</td><td>Hiện đúng thông báo của backend thay cho câu chung</td></tr><tr><td>Thông báo do backend tạo</td><td>Đạt</td><td>Thông báo giao Task thật hiện tiếng Anh</td></tr><tr><td>Đăng xuất Admin</td><td>Đạt</td><td>Trước đây Admin không có đường đăng xuất</td></tr><tr><td>PDF Admin <code>en</code>, <code>vi</code>, không truyền</td><td>Đạt</td><td>Một ngôn ngữ khi có <code>language</code>, hai ngôn ngữ khi không truyền</td></tr><tr><td>Chân email hàng loạt theo <code>working_language</code></td><td>Đạt</td><td><code>en</code>, <code>vi</code> đúng ngôn ngữ, rỗng nhận cả hai. Đọc từ <code>admin_email_outbox</code>, chưa gửi email thật</td></tr><tr><td>Mất clip khi tắt app sau khi dừng quay</td><td>Đạt test tự động</td><td>Chưa thử trên máy thật: ghi vào <code>filePath</code> riêng và tắt app thật</td></tr></tbody></table><h2 id="luot-quet-them-2026-11-03" tabindex="-1">Lượt quét thêm (2026-11-03) <a class="header-anchor" href="#luot-quet-them-2026-11-03" aria-label="Permalink to &quot;Lượt quét thêm (2026-11-03)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Kết quả</th><th>Ghi chú</th></tr></thead><tbody><tr><td>Manager, Creator, Client, Admin: sáng + tiếng Việt</td><td>Đạt</td><td>Quét các màn trong menu và tối đa 2 màn con mỗi màn. 503 ở Tạo Video AI là do stack test không chạy dịch vụ AI</td></tr><tr><td>Bộ lọc loại Task</td><td>Đạt</td><td>Bỏ <code>VIDEO</code> backend không nhận (400), thêm <code>EVENT_PLAN</code>, <code>PRESS_RECOMMENDATION</code></td></tr><tr><td>Admin có Cài đặt</td><td>Đạt</td><td>Đổi giao diện, Cài đặt tài khoản, Bảo mật mở được. Ngôn ngữ chưa đổi thử trong lượt này</td></tr><tr><td>Owner xem Task</td><td>Đạt</td><td>Trước đây lỗi 403 làm Owner không mở được chi tiết Task. Giờ chỉ xem, ẩn bình luận và lịch sử duyệt</td></tr><tr><td>Owner với trình soạn thảo và mời Workspace</td><td>Đạt trên mobile và web</td><td>Ẩn vì API từ chối. Web đã kiểm tra trên trình duyệt bằng Owner thật, xem mục bên dưới</td></tr><tr><td>Email OTP, đặt lại mật khẩu, mời Agency, mời Workspace, kích hoạt</td><td>Đạt qua Mailpit</td><td>Có <code>working_language</code> thì một ngôn ngữ, không có thì hai ngôn ngữ. Mã và link có đủ ở cả hai phần. SMTP cục bộ, chưa gửi email thật</td></tr></tbody></table><h2 id="test-backend-ban-build-sach" tabindex="-1">Test backend bản build sạch <a class="header-anchor" href="#test-backend-ban-build-sach" aria-label="Permalink to &quot;Test backend bản build sạch&quot;">​</a></h2><p>Biên dịch <code>clean</code> trên bản sao, bật test DB bằng <code>ADMIN_TEST_DB_URL</code>: 1454 test, 12 lỗi, 42 skip. Cả 12 lỗi đều có trên code gốc khi chạy cùng DB: <code>AiCreditDatabaseTest</code> 6, <code>AiVideoDatabaseTest</code> 5, <code>AdminFinanceDatabaseTest</code> 1.</p><p>Kết quả cũ &quot;1454 test, 0 lỗi, 80 skip&quot; của lượt sửa email và PDF không dùng được: Maven khi đó không biên dịch lại vì <code>target/classes</code> đã bị tiện ích Java của IDE ghi đè. Cần chạy <code>mvn clean</code> trước khi tin kết quả test.</p><h2 id="sua-test-db-nhanh-fix-backend-db-tests-cua-backend" tabindex="-1">Sửa test DB (nhánh <code>fix/backend-db-tests</code> của backend) <a class="header-anchor" href="#sua-test-db-nhanh-fix-backend-db-tests-cua-backend" aria-label="Permalink to &quot;Sửa test DB (nhánh `fix/backend-db-tests` của backend)&quot;">​</a></h2><p>12 test lỗi đều do test cũ, không có lỗi thật về tiền hay credit. Fixture AI Credit dùng đồng hồ thật của DB trong khi service dùng đồng hồ cố định, nên hỏng từ khi qua ngày 2026-10-31. Test báo cáo doanh thu tạo giao dịch kiểu cũ, trong khi báo cáo chỉ tính biên lai SePay đã xác minh.</p><p>Kết quả build sạch: 1439 test, 0 lỗi, 42 skip.</p><p>Trong nhóm skip, <code>MailStorePostgresTest</code> và <code>UserOAuthProviderRepositoryTest</code> đạt khi bật riêng. Các test còn lại chưa chạy được vì ghi cứng môi trường (cổng và tên DB như <code>55438/partner_test</code>, <code>55439/package_test</code>, replica set <code>taskWorkflowTest</code>) hoặc cần migration Mongo riêng. <code>*AtlasInventoryTest</code> đọc Atlas thật và <code>PaymentApiTest</code> cần cả hệ thống thanh toán nên không bật.</p><h2 id="kiem-tra-tren-ban-ghep-backend-va-quet-sau" tabindex="-1">Kiểm tra trên bản ghép backend và quét sâu <a class="header-anchor" href="#kiem-tra-tren-ban-ghep-backend-va-quet-sau" aria-label="Permalink to &quot;Kiểm tra trên bản ghép backend và quét sâu&quot;">​</a></h2><p>Backend ghép <code>feat/mobile-video-task-sync</code> với <code>fix/backend-db-tests</code>, build sạch: 1454 test, 0 lỗi, 42 skip.</p><p>Owner thật là chủ agency nhưng không là thành viên workspace (<code>myRole=OWNER</code>). Tài khoản <code>user177</code> trong seed có <code>myRole=MANAGER</code> nên không dùng để thử vai trò này được.</p><table tabindex="0"><thead><tr><th>Mục</th><th>Kết quả</th><th>Ghi chú</th></tr></thead><tbody><tr><td>Web, Owner mở Task</td><td>Đạt</td><td>Không có bình luận, nút Editor, ô phân công. Không còn 403 từ <code>/post</code>. Vào <code>/editor</code> bị chuyển về <code>/dashboard</code></td></tr><tr><td>Web, Manager mở Task</td><td>Đạt</td><td>Vẫn có ô phân công</td></tr><tr><td>Expo Web, Owner mở Task</td><td>Đạt</td><td>Không có request 403</td></tr><tr><td>Expo Web, Admin đổi ngôn ngữ</td><td>Đạt</td><td>Đổi ngay, tải lại vẫn giữ, không bị đẩy khỏi Cài đặt</td></tr><tr><td>Quét màn con, sáng + tiếng Việt, khổ 412px</td><td>Đạt</td><td>Manager 16 menu, Owner 14, Creator 9, Client 9, Admin 9, tối đa 6 màn con mỗi menu. Script kiểm tra chữ tiếng Anh, độ tương phản, tràn ngang, thông báo lỗi và request lỗi</td></tr></tbody></table><p>Giới hạn của lượt quét: dữ liệu seed không có Task nên chỉ dùng 1 Task tạo tay. Script bỏ qua nút có tác động như xoá, duyệt, gửi. Nhiều menu không có màn con để mở. Các tab Dashboard, Task, Lịch, Chat không nằm trong lượt này.</p><h2 id="sau-khi-merge-develop-co-da-996" tabindex="-1">Sau khi merge <code>develop</code> có DA-996 <a class="header-anchor" href="#sau-khi-merge-develop-co-da-996" aria-label="Permalink to &quot;Sau khi merge `develop` có DA-996&quot;">​</a></h2><p>Merge vào web và backend, xung đột 1 chỗ phần import ở <code>TaskWorkflowContent.tsx</code>. Phát hiện <code>WorkspaceTaskReader</code> bản mới từ chối <code>IN_REVIEW</code> và <code>FINISHED</code>, làm hỏng bộ lọc trên web và mobile; đã sửa cùng phân trang sai và 2 mục sidebar <code>/publish</code>.</p><table tabindex="0"><thead><tr><th>Mục</th><th>Kết quả</th></tr></thead><tbody><tr><td>Backend, ghép thêm <code>fix/backend-db-tests</code>, build sạch</td><td>1467 test, 0 lỗi, 42 skip</td></tr><tr><td>Web</td><td>104/104, <code>tsc</code> sạch</td></tr><tr><td>Mobile</td><td>295/295, <code>tsc</code> sạch</td></tr><tr><td>Web, lọc Chờ duyệt, Hoàn thành, Cần làm</td><td>Đạt, gồm cả Task cũ <code>MANAGER_REVIEW</code>, <code>COMPLETED</code></td></tr><tr><td>Expo Web, tab Pending review</td><td>Đạt</td></tr><tr><td>Survey trên web, Manager</td><td>Thẻ khảo sát và màn soạn mở được. Chưa thử xuất bản, trang công khai, Google Sheets</td></tr></tbody></table><h2 id="quay-va-tai-len-ben-hon-2026-11-04" tabindex="-1">Quay và tải lên bền hơn (2026-11-04) <a class="header-anchor" href="#quay-va-tai-len-ben-hon-2026-11-04" aria-label="Permalink to &quot;Quay và tải lên bền hơn (2026-11-04)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Kết quả</th><th>Ghi chú</th></tr></thead><tbody><tr><td>Backend, build sạch</td><td>1479 test, 0 lỗi, 82 skip</td><td>Không bật test DB</td></tr><tr><td>Mobile</td><td>312/312, <code>tsc</code> sạch</td><td>Service và màn quay chạy với mock</td></tr><tr><td>Tải theo phần trên server S3 thật</td><td>Đạt</td><td>RustFS qua <code>S3_TEST_ENDPOINT</code>: ký URL, gửi lại phần, ghép, copy, huỷ. Chưa thử trên AWS S3. Chưa chạy luồng API đủ Postgres và Mongo</td></tr><tr><td>Biên dịch Kotlin, gộp manifest Android</td><td>Đạt</td><td>Chưa build APK, chưa chạy trên emulator</td></tr><tr><td>Thông báo tiến độ, tải tiếp khi ra nền, giữ màn hình sáng, dừng khi ra nền, &quot;Dùng take này&quot;</td><td>Chưa chạy trên thiết bị</td><td>Cần emulator hoặc máy thật</td></tr><tr><td>iOS</td><td>Chưa build</td><td>Cần Mac hoặc EAS Build</td></tr></tbody></table><p>Cần thử trên máy thật: để màn quay quá thời gian khoá màn hình; bấm Home khi đang quay; có cuộc gọi đến khi đang quay; clip trên 1 GB trên iPhone và tắt mạng giữa chừng.</p><h2 id="sua-survey-sau-khi-kiem-tra-da-996" tabindex="-1">Sửa Survey sau khi kiểm tra DA-996 <a class="header-anchor" href="#sua-survey-sau-khi-kiem-tra-da-996" aria-label="Permalink to &quot;Sửa Survey sau khi kiểm tra DA-996&quot;">​</a></h2><ul><li>API công khai kiểm tra câu trả lời theo câu hỏi của khảo sát, giới hạn 5000 ký tự mỗi câu trả lời văn bản và 60 lần gửi mỗi phút theo IP cho từng khảo sát.</li><li>Chỉ Manager và Creator lưu được khảo sát. Owner và Client chỉ xem câu trả lời.</li><li>Mobile thay cảnh báo đỏ bằng lời nhắc mở khảo sát trên web.</li></ul><p>Kết quả test tự động: backend ghép thêm <code>fix/backend-db-tests</code>, có DB test, đạt 1472 test, 0 lỗi, 42 skip; web 104/104; mobile 295/295.</p><table tabindex="0"><thead><tr><th>Mục</th><th>Kết quả</th></tr></thead><tbody><tr><td>API công khai, 10 kiểu dữ liệu sai gồm giá trị 2MB</td><td>Đều trả 400</td></tr><tr><td>70 lần gửi cùng IP</td><td>60 đạt, 10 trả 429; IP khác vẫn gửi được</td></tr><tr><td>Lưu khảo sát</td><td>Manager, Creator đạt; Owner, Client trả 403</td></tr><tr><td>Web, Owner và Client</td><td>Chỉ thấy tab câu trả lời, không có nút lưu, không có request lỗi</td></tr><tr><td>Web, Creator</td><td>Vẫn mở được màn soạn đầy đủ</td></tr><tr><td>Trang công khai, 5 loại câu hỏi</td><td>Gửi đạt, dữ liệu lưu đúng</td></tr><tr><td>Expo Web, Task Survey</td><td>Hiện lời nhắc mở trên web, không còn cảnh báo đỏ; nhãn drawer đã dịch</td></tr></tbody></table><p>Chưa kiểm tra: Google Sheets và thiết bị thật.</p>',46)])])}const b=d(h,[["render",i]]);export{s as __pageData,b as default};
